// SPDX-License-Identifier: GPL-2.0-or-later
/**
 * The attachments of an invoice ( BG-24 ) - read, classified and rendered for `<einvoice-viewer>`.
 *
 * The viewer shows a section "Attachments" with one row per supporting document: reference ( BT-122 ),
 * description ( BT-123 ), file name ( BT-125-2 ), type ( BT-125-1 ), size, and the external address
 * ( BT-124 ) as a link. A PDF or an image can be viewed in place, an allowed type can be saved, and a
 * type outside the allow-list is named but neither opened nor offered.
 *
 * ⚠️ **THE INVOICE IS UNTRUSTED INPUT, AND SO IS EVERY ATTACHMENT IN IT.** Four consequences, each one
 * a rule in this file:
 *
 *   1. Every text from the invoice goes through `esc()` before it reaches markup - the file name
 *      included. A file name is chosen by the sender and can be `<img src=x onerror=…>`.
 *   2. The MIME type of a blob comes from the allow-list below, never from the invoice. The invoice
 *      only selects an entry of the list; a type that is not in it gets no blob at all.
 *   3. The bytes are checked against the declared type before they are shown or saved ( `matchesType()` ).
 *      An attachment that calls itself `application/pdf` and starts with `<html>` is refused.
 *   4. SVG and HTML are not in the list and never will be: both can carry script.
 *
 * ⚠️ **BASE64 IS DECODED ONLY WHEN SOMEONE OPENS OR SAVES AN ATTACHMENT, NEVER WHILE THE PAGE LOADS.**
 * `readAttachments()` measures the size by counting characters and keeps a reference to the XML
 * element; `decodeBase64()` runs from a click handler only. An invoice with five 10-MB attachments
 * would otherwise cost 50 MB of memory and a noticeable pause before the reader has asked for any of
 * them.
 *
 * ⚠️ **THE SECTION IS READ FROM THE PARSED XML, NOT FROM THE MODEL.** The model's "Supporting documents"
 * cards are shared with the PHP renderer and kept byte-equal to it ( `compare-render.mjs` ), and the
 * PHP side does not read `@mimeCode` / `@filename` ( see `attachmentCards()` in `ModelAssembler.mjs` ).
 * The PHP side also reads UBL through a CII conversion that drops BT-124 ( see `compare-ubl-attachments.mjs` ),
 * so the model cards differ from the invoice there. The tender reference that the conversion
 * turns into a card with type code 50 is filtered out on both sides.
 * Reading the DOM directly gives both syntaxes and both attributes without touching the parity of the
 * model.
 *
 * ⚠️ **THE VIEWER DOES NOT DRAW THOSE CARDS** ( `withoutSupportingDocumentCards()`
 * below ). They stay in the model for the PHP parity, the inbound apps and the exporter add-on.
 *
 * @since 0.16.0
 */

import { t, tf } from './Labels.mjs';
import { formatNum } from './Format.mjs';
import { supportingDocTypeLabel } from './Codelists.mjs';


/**
 * The types an attachment may have, after EN 16931 ( BT-125-1, code list "MIME code" ).
 *
 * ⚠️ **SIX TYPES, AND THE LIST IS THE NORM'S, NOT OURS.** EN 16931 and XRechnung allow exactly
 * `application/pdf`, `image/png`, `image/jpeg`, `text/csv`, the XLSX type and the ODS type. Anything
 * else is a breach of the norm and, more to the point, a file we cannot vouch for.
 *
 * `view` says how the type is shown in place: `pdf` through pdf.js, `image` as an `<img>`, `null` not
 * at all ( it can only be saved ).
 *
 * `magic` are the first bytes the content must start with. ⚠️ CSV has none: it is plain text, and
 * any byte sequence is a valid CSV. It is saved as `text/csv` with a `.csv` extension, so the system
 * opens it in a spreadsheet or text editor, never as a program.
 *
 * ⚠️ XLSX and ODS are both ZIP containers and share the ZIP signature. That does not prove the
 * container holds a spreadsheet, but it does exclude the case that matters here - a different file
 * type passed off under a spreadsheet name.
 */

export const ALLOWED_TYPES = Object.freeze( {
	'application/pdf': { ext: [ 'pdf' ], view: 'pdf', magic: [ [ 0x25, 0x50, 0x44, 0x46, 0x2D ] ] },
	'image/png':       { ext: [ 'png' ], view: 'image', magic: [ [ 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A ] ] },
	'image/jpeg':      { ext: [ 'jpg', 'jpeg' ], view: 'image', magic: [ [ 0xFF, 0xD8, 0xFF ] ] },
	'text/csv':        { ext: [ 'csv' ], view: null, magic: null },
	'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': { ext: [ 'xlsx' ], view: null, magic: [ [ 0x50, 0x4B, 0x03, 0x04 ] ] },
	'application/vnd.oasis.opendocument.spreadsheet': { ext: [ 'ods' ], view: null, magic: [ [ 0x50, 0x4B, 0x03, 0x04 ] ] },
} );


/**
 * The `TypeCode` / `DocumentTypeCode` values that turn an `AdditionalReferencedDocument` into
 * something other than a supporting document.
 *
 * ⚠️ **CII AND UBL USE ONE ELEMENT FOR THREE BUSINESS TERMS.** `130` is the invoiced object identifier
 * ( BT-18 ), `50` the tender or lot reference ( BT-17 ), and only the rest - in CII `916` - is BG-24.
 * Listing a `130` as an attachment would offer the reader a file that is in fact a meter number.
 *
 * ⚠️ **THE SAME LIST STANDS IN `ModelAssembler.mjs` ( `NOT_A_SUPPORTING_DOCUMENT` ) AND IN
 * `ModelBuilder.php`**, and the model filters the cards with it. BT-17 and BT-18 are
 * rows of "Order & contract data" there. A code added here has to be added in both other places.
 */

const NOT_AN_ATTACHMENT = [ '130', '50' ];


/**
 * The direct element children of a node, by local name.
 *
 * ⚠️ **LOCAL NAME, NOT PREFIX.** A sender may call the CII namespace `ram:` or anything else; a lookup
 * by `ram:Name` would miss every invoice that does not use the customary prefix.
 *
 * @param {Element} node
 * @param {string} name
 * @return {Element[]}
 */

function children( node, name ) {

	const out = [];

	for ( const c of Array.from( node ? node.childNodes : [] ) )
		if ( c.nodeType === 1 && localName( c ) === name )
			out.push( c );

	return out;

}

/**
 * The local name of an element.
 *
 * ⚠️ **NOT `el.localName` ALONE.** Browsers give `Name` for `ram:Name`; linkedom, which the tests use,
 * gives `ram:Name` ( measured 08.10.2026 ). Stripping everything up to the colon gives the same result
 * in both.
 *
 * @param {Element} el
 * @return {string}
 */

function localName( el ) {

	return String( el.localName || el.nodeName || '' ).replace( /^.*:/, '' );

}

/** The first direct child of that local name, or null. */
function child( node, name ) {

	return children( node, name )[ 0 ] || null;

}

/** The trimmed text of the first direct child of that local name, or ''. */
function text( node, name ) {

	const c = child( node, name );

	return c ? String( c.textContent || '' ).trim() : '';

}


/**
 * Strips the parameters from a MIME type and lower-cases it.
 *
 * `text/csv; charset=utf-8` and `Text/CSV` both become `text/csv`. Parameters do not change what kind
 * of file it is, and a case difference is not a different type ( RFC 2045 ).
 *
 * @param {string} mime
 * @return {string}
 */

export function normaliseMime( mime ) {

	return String( mime ?? '' ).split( ';' )[ 0 ].trim().toLowerCase();

}


/**
 * The decoded size of a base64 text, without decoding it.
 *
 * ⚠️ **COUNTED, NOT DECODED, AND THAT IS THE WHOLE POINT.** Four characters carry three bytes, and up
 * to two `=` at the end carry none. White space inside the text ( line breaks every 76 characters are
 * common ) does not count. A loop over the characters costs a few milliseconds for 10 MB and
 * allocates nothing; `atob()` would allocate the whole file.
 *
 * @param {string} b64
 * @return {number} Bytes.
 */

export function base64Size( b64 ) {

	const s = String( b64 ?? '' );

	let chars = 0;
	let pad = 0;

	for ( let i = 0; i < s.length; i++ ) {

		const c = s.charCodeAt( i );

		// space, tab, CR, LF
		if ( c === 32 || c === 9 || c === 13 || c === 10 ) continue;

		chars++;

		pad = c === 61 /* = */ ? pad + 1 : 0;

	}

	return Math.max( 0, Math.floor( chars / 4 ) * 3 - Math.min( pad, 2 ) );

}


/**
 * The attachments of an invoice, read from its parsed XML.
 *
 * Returns one entry per supporting document in document order. The entry carries the texts and the
 * measured size, but **not** the content: `content()` reads it from the XML element when it is called.
 *
 * ⚠️ **HEADER LEVEL ONLY.** BG-24 sits under `ApplicableHeaderTradeAgreement` in CII and directly under
 * the root in UBL. A CII invoice line can carry its own `AdditionalReferencedDocument` too - that one
 * is the line object identifier ( BT-128 ), not an attachment, and walking the whole tree with
 * `getElementsByTagName()` would list it.
 *
 * @param {Document} doc The parsed invoice.
 * @return {Array<{index: number, id: string, typeCode: string, description: string, uri: string,
 *          fileName: string, mime: string, hasContent: boolean, size: number, content: () => string}>}
 */

export function readAttachments( doc ) {

	const root = doc && doc.documentElement;

	if ( ! root ) return [];

	const rootName = localName( root );

	let elements = [];
	let ubl = false;

	if ( rootName === 'CrossIndustryInvoice' ) {

		const agreement = child( child( root, 'SupplyChainTradeTransaction' ), 'ApplicableHeaderTradeAgreement' );

		elements = children( agreement, 'AdditionalReferencedDocument' );

	} else if ( rootName === 'Invoice' || rootName === 'CreditNote' ) {

		ubl = true;
		elements = children( root, 'AdditionalDocumentReference' );

	}

	const out = [];

	for ( const el of elements ) {

		const typeCode = ubl ? text( el, 'DocumentTypeCode' ) : text( el, 'TypeCode' );

		if ( NOT_AN_ATTACHMENT.indexOf( typeCode ) >= 0 ) continue;

		const attachment = ubl ? child( el, 'Attachment' ) : null;

		const bin = ubl
			? child( attachment, 'EmbeddedDocumentBinaryObject' )
			: child( el, 'AttachmentBinaryObject' );

		const uri = ubl
			? text( child( attachment, 'ExternalReference' ), 'URI' )
			: text( el, 'URIID' );

		// ⚠️ `textContent` of a text-only element hands back the string the parser already holds; it is
		// read here once to measure it and dropped again - the entry keeps the element, not the text.
		const raw = bin ? String( bin.textContent || '' ) : '';

		out.push( {
			index: out.length,
			id: ubl ? text( el, 'ID' ) : text( el, 'IssuerAssignedID' ),
			// ⚠️ Read from the invoice as it is. A UBL invoice may leave the type out; the section then shows a
			// dash and never the 916 that the PHP conversion to CII has to write ( see Reader.php,
			// restoreReferenceTypeCodes() ).
			typeCode,
			description: ubl ? text( el, 'DocumentDescription' ) : text( el, 'Name' ),
			uri,
			fileName: bin ? String( bin.getAttribute( 'filename' ) || '' ).trim() : '',
			mime: bin ? String( bin.getAttribute( 'mimeCode' ) || '' ).trim() : '',
			hasContent: raw.trim() !== '',
			size: base64Size( raw ),
			content: () => ( bin ? String( bin.textContent || '' ) : '' ),
		} );

	}

	return out;

}


/**
 * What may be done with an attachment.
 *
 * @param {{mime: string, hasContent: boolean}} att
 * @return {{kind: 'none'|'blocked'|'allowed', type: object|null, mime: string}}
 *         `none` = no embedded file ( only a reference or a link ), `blocked` = a type outside the
 *         allow-list, `allowed` = in the list; `type` is its entry in `ALLOWED_TYPES`.
 */

export function classify( att ) {

	const mime = normaliseMime( att && att.mime );

	if ( ! att || ! att.hasContent ) return { kind: 'none', type: null, mime };

	const type = Object.prototype.hasOwnProperty.call( ALLOWED_TYPES, mime ) ? ALLOWED_TYPES[ mime ] : null;

	return { kind: type ? 'allowed' : 'blocked', type, mime };

}


/**
 * Decodes base64 into bytes.
 *
 * ⚠️ **ONLY FROM A CLICK HANDLER.** See the head of this file.
 *
 * ⚠️ **STRICT.** `atob()` tolerates some malformed input silently in some engines; a character outside
 * the base64 alphabet is refused here instead, so a broken attachment ends in a message and not in a
 * truncated file that looks fine.
 *
 * @param {string} b64
 * @return {Uint8Array}
 * @throws {Error} on characters outside the alphabet.
 */

export function decodeBase64( b64 ) {

	const clean = String( b64 ?? '' ).replace( /[\s]+/g, '' );

	if ( ! /^[A-Za-z0-9+/]*={0,2}$/.test( clean ) || clean.length % 4 === 1 )
		throw new Error( 'invalid base64' );

	const bin = atob( clean );
	const bytes = new Uint8Array( bin.length );

	for ( let i = 0; i < bin.length; i++ ) bytes[ i ] = bin.charCodeAt( i );

	return bytes;

}


/**
 * Do the bytes start the way the declared type requires?
 *
 * @param {object} type An entry of `ALLOWED_TYPES`.
 * @param {Uint8Array} bytes
 * @return {boolean}
 */

export function matchesType( type, bytes ) {

	if ( ! type ) return false;

	if ( ! type.magic ) return true;

	return type.magic.some( ( sig ) => sig.every( ( b, i ) => bytes[ i ] === b ) );

}


/**
 * A file name that is safe to hand to the browser's download.
 *
 * ⚠️ **THE NAME IS THE SENDER'S, AND A SENDER CAN WRITE ANYTHING INTO IT.** Measured in the corpus:
 * `CIUS-PT/I_CIUS-PT_syntax-model - F.xml` calls its PDF `$%()*`. Four things are done here:
 *
 *   1. Only the last path segment is kept - `..\..\autostart\x.pdf` becomes `x.pdf`.
 *   2. Characters that no file system takes ( `< > : " / \ | ? *` and control characters ) are replaced
 *      by `_`, and leading dots are removed, so the file is neither hidden nor a path.
 *   3. A name that Windows reserves ( `CON`, `NUL`, `COM1` … ) gets a leading `_`.
 *   4. ⚠️ **THE EXTENSION FOLLOWS THE TYPE, NOT THE NAME.** A PDF called `rechnung.exe` is saved as
 *      `rechnung.exe.pdf`. The system then opens it as what it was checked to be.
 *
 * @param {{fileName: string, id: string}} att
 * @param {object|null} type An entry of `ALLOWED_TYPES`.
 * @return {string}
 */

export function safeFileName( att, type ) {

	let name = String( ( att && ( att.fileName || att.id ) ) || '' );

	name = name.split( /[\\/]/ ).pop();

	// eslint-disable-next-line no-control-regex
	name = name.replace( /[\u0000-\u001F\u007F<>:"|?*]/g, '_' ).replace( /\s+/g, ' ' ).trim();

	name = name.replace( /^[.\s]+/, '' ).replace( /[.\s]+$/, '' );

	if ( name.length > 120 ) name = name.slice( 0, 120 ).trim();

	if ( name === '' ) name = 'attachment';

	if ( /^(con|prn|aux|nul|com[0-9]|lpt[0-9])(\.|$)/i.test( name ) ) name = '_' + name;

	if ( type && type.ext && type.ext.length ) {

		const dot = name.lastIndexOf( '.' );
		const ext = dot > 0 ? name.slice( dot + 1 ).toLowerCase() : '';

		if ( type.ext.indexOf( ext ) < 0 ) name += '.' + type.ext[ 0 ];

	}

	return name;

}


/**
 * A size for people: bytes, KB or MB, in the number format of the active language.
 *
 * ⚠️ **THE UNITS ARE NOT TRANSLATED.** `KB` and `MB` are symbols and read the same in German, English
 * and French. The number goes through `formatNum()`, so it carries the decimal comma in German and
 * French - which is why this function must run after `build()` has set the format language.
 *
 * @param {number} bytes
 * @return {string}
 */

export function formatSize( bytes ) {

	const n = Number( bytes ) || 0;

	if ( n < 1024 ) return formatNum( n ) + ' B';

	if ( n < 1024 * 1024 ) return formatNum( ( n / 1024 ).toFixed( 1 ) ) + ' KB';

	return formatNum( ( n / ( 1024 * 1024 ) ).toFixed( 1 ) ) + ' MB';

}


/** Text for an element body or an attribute in double quotes - see `QubaTemplate.mjs`'s `esc()`. */
function esc( value ) {

	return String( value ?? '' )
		.replace( /&/g, '&amp;' )
		.replace( /</g, '&lt;' )
		.replace( />/g, '&gt;' )
		.replace( /"/g, '&quot;' )
		.replace( /'/g, '&#039;' );

}

/**
 * Is this an address the reader may follow?
 *
 * ⚠️ **ONLY `http:` AND `https:`.** BT-124 is free text. `javascript:…` in an `href` would run on
 * click, `file:` would point into the reader's own disk. Everything else is shown as text.
 *
 * @param {string} uri
 * @return {boolean}
 */

export function isWebAddress( uri ) {

	return /^https?:\/\/[^\s]+$/i.test( String( uri ?? '' ).trim() );

}

/** A code badge, the same markup as `bt()` in `QubaTemplate.mjs`. */
function badge( code, tooltipFor ) {

	const title = tooltipFor ? tooltipFor( code ) : '';

	return ' <span class="badge code spev-bt"'
		+ ( title ? ' data-spev-tip="' + esc( title ) + '" tabindex="0"' : '' )
		+ '>' + esc( code ) + '</span>';

}


/**
 * The section "Attachments" as HTML, or '' when the invoice has none.
 *
 * ⚠️ **KIT CLASSES ONLY.** `doc-grid`, `doc-block full`, `doc-block-head`, `spev-table-wrap` and `tbl`
 * are the same building blocks the tables of the invoice view use ( `renderTable()` in
 * `QubaTemplate.mjs` ); `btn small` and `btn small ghost` are the kit's buttons, `sub` its secondary
 * line, `note warn` its notice. The classes starting with `spev-att` carry no rule in any stylesheet -
 * they are the hooks the click handler of `<einvoice-viewer>` looks for.
 *
 * ⚠️ **THE BUTTONS CARRY THE INDEX, NOT THE CONTENT.** A `data-` attribute with the base64 in it would
 * put the whole file into the DOM a second time and decode nothing later.
 *
 * @param {Array<object>} list From `readAttachments()`.
 * @param {{tooltipFor?: (code:string)=>string, canPreviewPdf?: boolean}} [opts]
 *        `canPreviewPdf` = a pdf.js source is configured; without one a PDF can only be saved.
 * @return {string}
 */

export function renderAttachments( list, opts = {} ) {

	if ( ! list || ! list.length ) return '';

	const tip = opts.tooltipFor || null;

	/*
	 * ⚠️ **SIX OF THE SEVEN HEADINGS ARE THE LABELS OF THE "ADDITIONAL SUPPORTING DOCUMENTS" CARD**, word for word
	 * ( `attachmentCards()` in `ModelAssembler.mjs` ). They are translated already, and the inbound apps,
	 * which still draw the card, use the same name for the same field.
	 */
	const head = [
		[ t( 'Identifier' ), 'BT-122', false ],
		[ t( 'Type of referenced document' ), 'BT-122-0', false ],
		[ t( 'Attachment description' ), 'BT-123', false ],
		[ t( 'Attachment file name' ), 'BT-125-2', false ],
		[ t( 'Attachment format' ), 'BT-125-1', false ],
		[ t( 'Size' ), '', true ],
		[ t( 'Reference (URL)' ), 'BT-124', false ],
		[ '', '', false ],
	];

	/*
	 * ⚠️ **THE BT NUMBER STANDS IN EACH CELL, NOT IN THE HEADING** - the same form as the tables of the
	 * invoice view ( `renderTable()` in `QubaTemplate.mjs` ): a `spev-cell-bt` line above the value. With the
	 * badges in the headings, seven headings with a number each were wider than the viewer, and the
	 * section had to scroll sideways. A heading without its badge also wraps more freely.
	 */
	let thead = '';

	for ( const [ label, , num ] of head )
		thead += '<th' + ( num ? ' class="num"' : '' ) + '>' + esc( label ) + '</th>';

	// One cell in the form of renderTable(): the badge line, then the value.
	const cell = ( i, html, cls = '' ) => {
		const code = head[ i ][ 1 ];
		return '<td' + ( cls ? ' class="' + cls + '"' : '' ) + '>'
			+ ( code ? '<div class="spev-cell-bt">' + badge( code, tip ) + '</div>' : '' ) + html + '</td>';
	};

	let tbody = '';

	for ( const att of list ) {

		const c = classify( att );
		const dash = '—';

		let typeCell = att.mime !== '' ? esc( att.mime ) : dash;
		let actions = '';
		let rowCls = '';

		if ( c.kind === 'blocked' ) {

			/*
			 * ⚠️ **NAMED, NOT OFFERED.** The row stays, with the type the invoice declares and a sentence
			 * that says why there is no button. Leaving the row out would hide that the invoice carries a
			 * file at all; offering it would hand an unchecked file to the reader's system.
			 */
			rowCls = ' class="edge-warn"';
			typeCell += '<span class="sub">' + esc( t( 'This file type is not allowed in an e-invoice. It is neither opened nor offered for saving.' ) ) + '</span>';

		} else if ( c.kind === 'allowed' ) {

			const canView = c.type.view === 'image' || ( c.type.view === 'pdf' && opts.canPreviewPdf );

			if ( canView )
				actions += '<button type="button" class="btn small spev-att-view" data-spev-att="' + att.index + '">' + esc( t( 'View' ) ) + '</button> ';

			actions += '<button type="button" class="btn small ghost spev-att-save" data-spev-att="' + att.index + '">' + esc( t( 'Save' ) ) + '</button>';

		}

		/*
		 * ⚠️ **A LINK, AND NOTHING THAT LOADS IT.** No preview, no favicon, no prefetch: the browser
		 * contacts the address only when the reader clicks. `noopener` keeps the new tab from reaching
		 * back into this one, `noreferrer` and `referrerpolicy` keep the address of this page out of the
		 * sender's server log.
		 */
		const uriCell = att.uri === ''
			? dash
			: ( isWebAddress( att.uri )
				? '<a class="spev-link" href="' + esc( att.uri.trim() ) + '" target="_blank" rel="noopener noreferrer nofollow" referrerpolicy="no-referrer">' + esc( att.uri ) + '</a>'
				: esc( att.uri ) );

		tbody += '<tr' + rowCls + '>'
			+ cell( 0, att.id !== '' ? esc( att.id ) : dash )
			+ cell( 1, att.typeCode ? esc( supportingDocTypeLabel( att.typeCode ) ) : dash )
			+ cell( 2, att.description !== '' ? esc( att.description ) : dash )
			+ cell( 3, att.fileName !== '' ? esc( att.fileName ) : dash )
			+ cell( 4, typeCell )
			+ cell( 5, att.hasContent ? esc( formatSize( att.size ) ) : dash, 'num' )
			+ cell( 6, uriCell )
			+ cell( 7, actions, 'nowrap' )
			+ '</tr>';

	}

	return '<div class="doc-grid spev-attachments">'
		+ '<section class="doc-block full">'
		+ '<h3 class="doc-block-head">' + esc( t( 'Attachments' ) ) + badge( 'BG-24', tip ) + '</h3>'
		+ '<div class="spev-table-wrap"><table class="tbl"><thead><tr>' + thead + '</tr></thead><tbody>' + tbody + '</tbody></table></div>'
		+ '<div class="doc-block-body spev-att-preview" hidden></div>'
		+ '</section></div>';

}


/**
 * The original PDF of an invoice the caller has already read, as a section of its own.
 *
 * `<einvoice-viewer>` shows it only when `showResult()` hands in the bytes and the caller did not
 * switch it off; the inbound plugin does that, because it has no other place for the PDF.
 *
 * ⚠️ **NOT A ROW OF THE SECTION "ATTACHMENTS".** That section is BG-24, the documents the invoice refers
 * to, with one BT column after the other. The PDF a ZUGFeRD invoice came in has none of those terms; as a
 * row it would stand there with five dashes and pretend to be a supporting document.
 *
 * ⚠️ **THE BUTTONS USE THE SAME HOOKS AS AN ATTACHMENT**, `spev-att-view` and `spev-att-save`, with the
 * index `original`. The click handler of the element decodes nothing for it ( the bytes are there ) but
 * runs the same type check, so a file that calls itself PDF and is something else is refused here too.
 *
 * ⚠️ **THE HEADING COMES FROM THE CALLER, NOT FROM THIS FILE'S TABLE.** The inbound plugin passes its own
 * translated "Original (visible document)", the word its apps use for the same document. A text of its
 * own here would land in the anchor file of every package that ships this module - the viewer and the
 * three validators, none of which ever shows the section - and their language check would block each
 * release until four `.po` files carried a sentence no reader of theirs sees. Measured on 08.10.2026:
 * `check-languages.php` reported it as missing for exactly those four packages. Without a heading the
 * file name stands there, which needs no translation.
 *
 * @param {{fileName: string, size: number}} original  The pseudo attachment built by `showResult()`.
 * @param {{canPreviewPdf?: boolean, title?: string}} [opts]
 * @return {string}
 */

export function renderOriginal( original, opts = {} ) {

	if ( ! original ) return '';

	const view = opts.canPreviewPdf
		? '<button type="button" class="btn small spev-att-view" data-spev-att="original">' + esc( t( 'View' ) ) + '</button> '
		: '';

	const title = String( opts.title || original.fileName || 'PDF' );

	return '<div class="doc-grid spev-original">'
		+ '<section class="doc-block full">'
		+ '<h3 class="doc-block-head">' + esc( title ) + '</h3>'
		+ '<div class="spev-table-wrap"><table class="tbl"><tbody><tr>'
		+ '<td>' + ( original.fileName ? esc( original.fileName ) : '—' ) + '</td>'
		+ '<td>application/pdf</td>'
		+ '<td class="num">' + esc( formatSize( original.size ) ) + '</td>'
		+ '<td class="nowrap">' + view
		+ '<button type="button" class="btn small ghost spev-att-save" data-spev-att="original">' + esc( t( 'Save' ) ) + '</button></td>'
		+ '</tr></tbody></table></div>'
		+ '<div class="doc-block-body spev-att-preview" hidden></div>'
		+ '</section></div>';

}


/**
 * The model the viewer draws: the same model without its "Supporting documents" cards ( BG-24 ).
 *
 * The viewer shows the attachments only in the section "Attachments" built by `renderAttachments()`.
 * With the cards as well, every CII invoice with an attachment would show the same
 * documents twice, once as a card per document inside the invoice and once as a row in the section.
 *
 * ⚠️ **THE CARDS LEAVE THE DRAWING, NOT THE MODEL.** `attachmentCards()` in `ModelAssembler.mjs` keeps
 * building them, because the model is shared: `compare-model.mjs` and `compare-render.mjs` hold it
 * byte-equal to `ModelBuilder.php` and `QubaTemplate.php`, the inbound apps draw it with the same
 * template, and the exporter add-on reads the model from the `einvoice-model-ready` event. Removing
 * the cards in the assembler or in the template would change all of these at once.
 *
 * ⚠️ **A COPY, NEVER AN EDIT IN PLACE.** `<einvoice-viewer>` hands the very same model object to the
 * `einvoice-model-ready` event and to `window.EInvoice.lastModel`. Filtering the arrays in place
 * would take the cards away from every add-on that reads the model after the drawing.
 *
 * ⚠️ **MATCHED ON THE CODE `BG-24`, NOT ON THE TITLE.** The title is translated ( "Rechnungsbegründende
 * Unterlagen" in German ), the code is not. Only cards are dropped; no table or totals block carries this code.
 *
 * @param {object} model From `build()`, possibly extended by an add-on.
 * @return {object} A shallow copy whose sections no longer contain a BG-24 card.
 */

export function withoutSupportingDocumentCards( model ) {

	if ( ! model || ! Array.isArray( model.sections ) ) return model;

	const isCard = ( item ) => item && item.kind === 'card' && item.bt === 'BG-24';

	return Object.assign( {}, model, {
		sections: model.sections.map( ( section ) => (
			section && Array.isArray( section.items ) && section.items.some( isCard )
				? Object.assign( {}, section, { items: section.items.filter( ( item ) => ! isCard( item ) ) } )
				: section
		) ),
	} );

}


/**
 * The sentence for an attachment that could not be shown or saved.
 *
 * @param {'decode'|'mismatch'|'pdfjs'|'render'} reason
 * @return {string}
 */

export function attachmentMessage( reason ) {

	switch ( reason ) {

		case 'decode':   return t( 'The attachment could not be decoded.' );
		case 'mismatch': return t( 'The content of this attachment does not match its declared file type. It is neither opened nor offered for saving.' );
		case 'pdfjs':    return t( 'The preview needs the PDF reader, which could not be loaded. The file can still be saved.' );

	}

	return t( 'The attachment could not be shown.' );

}


/**
 * The line under a PDF preview that was cut short.
 *
 * @param {number} shown
 * @param {number} total
 * @return {string}
 */

export function pagesNotice( shown, total ) {

	return tf( 'Only the first %1$d of %2$d pages are shown. Save the file to see all of them.', shown, total );

}
