/**
 * The design kit chosen in an app package, for the stylesheets of a shadow root.
 *
 * An app package links Kit H firmly and, when `designKit` in `config.js` chooses another kit, loads that kit's token
 * file after it ( `kitLader()` in `apps/build/package-parts.mjs` ). The loader leaves the address in
 * `window.einvoiceKitTokens`. A shadow root does not see the document's stylesheets, so every element that links its
 * own from `data-css` passes the list through kitStylesheets(), and the chosen token file joins the list right after
 * the default one.
 *
 * ⚠️ **ADDED BEHIND, NOT SWAPPED IN.** The default token file stays in the list. A chosen file that is missing, or an
 * own kit with a misspelt name, then leaves Kit H in place instead of a view without colours, surfaces and font sizes.
 *
 * ⚠️ **IN A WORDPRESS PLUGIN NOTHING HAPPENS.** There the variable is not set: the plugin already hands the chosen
 * kit's addresses to `data-css` ( `EInvoicePress_Design_Kit::stylesheets()` ), and the list stays as it is.
 *
 * Since 19.10.2026 ( Ralf: one switch, and the whole interface keeps to the kit ).
 */

/** A token file of the tool kit, under its own name: `spt-kit-<x>.tokens.css`, with or without a path or query. */
const TOKENS = /(^|\/)spt-kit-[a-z0-9-]+\.tokens\.css(\?.*)?$/;

/**
 * The list of stylesheet addresses, with the chosen kit behind the first token file.
 *
 * @param {string[]} urls the addresses from `data-css` or a built-in default list
 * @return {string[]}
 */
export function kitStylesheets( urls ) {

	const chosen = typeof globalThis !== 'undefined' && typeof globalThis.einvoiceKitTokens === 'string'
		? globalThis.einvoiceKitTokens
		: '';

	if ( chosen === '' || urls.includes( chosen ) )
		return urls;

	const at = urls.findIndex( ( u ) => TOKENS.test( u ) );

	if ( at === -1 )
		return urls;

	return [ ...urls.slice( 0, at + 1 ), chosen, ...urls.slice( at + 1 ) ];

}
