/**
 * The settings of the viewer's add-ons: one dialog, two stores.
 *
 * Every add-on that has settings registers a section with `viewer.addSettingsSection()`. The dialog, the backup file and
 * the business logic are the same JavaScript in the app and in the WordPress plugin; only the store differs:
 *
 *   - `LocalSettingsStore`  the app: the browser's `localStorage` of the page.
 *   - `RestSettingsStore`   the plugin: `einvoice-viewer/v1/settings` on the site, with the rights of the logged-in user.
 *
 * ⚠️ A SECTION IS REPLACED AS A WHOLE, NEVER MIXED FIELD BY FIELD. Saving, loading a backup and the conflict check all
 * work on whole sections; a supplier list half from the file and half from the store would be wrong in both.
 *
 * ⚠️ UNKNOWN SECTIONS STAY. A backup loaded into an app without the matching add-on is stored anyway and written again
 * unchanged by the next backup; otherwise moving a backup through an app without that add-on would lose it.
 *
 * ⚠️ ONLY USER SETTINGS. The backup file never carries operator settings ( `config.js`, roles, limits ) or keys for
 * services; a file passed on by mail must not leak a key.
 */

export const SETTINGS_FORMAT = 'einvoice-settings';
export const SETTINGS_FORMAT_VERSION = 1;


/**
 * The store of the app: one entry in `localStorage`.
 *
 * ⚠️ EVERY ACCESS TO `localStorage` MAY THROW ( private window, blocked site data, `file://` in some browsers ). Reading
 * then gives no sections, and saving answers with an error the dialog shows; nothing else breaks.
 */
export class LocalSettingsStore {

	constructor( key = 'einvoice-settings' ) {
		this.key = key;
	}

	/** @return {Promise<{sections: object, canWrite: boolean}>} */
	async load() {
		let sections = {};
		try {
			const raw = window.localStorage.getItem( this.key );
			const parsed = raw ? JSON.parse( raw ) : null;
			if ( parsed && typeof parsed.sections === 'object' && parsed.sections ) sections = parsed.sections;
		} catch ( e ) { sections = {}; }
		return { sections, canWrite: true };
	}

	/**
	 * @param {string} id
	 * @param {{version: number, data: any}} entry
	 * @param {number} rev the revision that was read; the app has one user, so it is only counted up
	 * @return {Promise<{ok: boolean, rev?: number, error?: string}>}
	 */
	async save( id, entry, rev ) {
		try {
			const { sections } = await this.load();
			const next = ( Number( sections[ id ] && sections[ id ].rev ) || 0 ) + 1;
			sections[ id ] = { version: Number( entry.version ) || 1, data: entry.data, rev: next };
			window.localStorage.setItem( this.key, JSON.stringify( { sections } ) );
			return { ok: true, rev: next };
		} catch ( e ) {
			return { ok: false, error: 'storage' };
		}
	}

}


/**
 * The store of the plugin: the REST routes `einvoice-viewer/v1/settings` of the site.
 *
 * ⚠️ THE NONCE IN `X-WP-Nonce`. WordPress accepts the login cookie for a REST write only together with the nonce
 * `wp_rest`; the plugin writes it into `data-settings-nonce`.
 *
 * ⚠️ THE REVISION GOES WITH EVERY SAVE. When somebody else saved the section in between, the site answers 409 and the
 * dialog says so instead of overwriting the other person's work.
 */
export class RestSettingsStore {

	constructor( url, nonce ) {
		this.url = String( url || '' ).replace( /\/+$/, '' );
		this.nonce = String( nonce || '' );
	}

	_headers() {
		const h = { 'Content-Type': 'application/json' };
		if ( this.nonce ) h[ 'X-WP-Nonce' ] = this.nonce;
		return h;
	}

	async load() {
		try {
			const r = await fetch( this.url, { credentials: 'same-origin', headers: this._headers() } );
			if ( ! r.ok ) return { sections: {}, canWrite: false };
			const d = await r.json();
			return { sections: ( d && d.sections ) || {}, canWrite: !! ( d && d.canWrite ), rights: ( d && d.rights ) || {} };
		} catch ( e ) {
			return { sections: {}, canWrite: false };
		}
	}

	async save( id, entry, rev ) {
		try {
			const r = await fetch( this.url + '/' + encodeURIComponent( id ), {
				method: 'PUT',
				credentials: 'same-origin',
				headers: this._headers(),
				body: JSON.stringify( { version: Number( entry.version ) || 1, data: entry.data, rev: Number( rev ) || 0 } ),
			} );
			if ( r.status === 409 ) return { ok: false, error: 'conflict' };
			if ( r.status === 401 || r.status === 403 ) return { ok: false, error: 'rights' };
			if ( ! r.ok ) return { ok: false, error: 'server' };
			const d = await r.json();
			return { ok: true, rev: Number( d && d.rev ) || ( Number( rev ) || 0 ) + 1 };
		} catch ( e ) {
			return { ok: false, error: 'server' };
		}
	}

}


/**
 * The backup file: a head and one entry per section, the stored ones and the unknown ones alike.
 *
 * @param {object} sections { id: { version, data } }
 * @param {object} source   { kind: 'app'|'plugin', product, version, api }
 * @return {string} JSON text
 */
export function buildBackup( sections, source ) {
	const out = {};
	for ( const id of Object.keys( sections || {} ) ) {
		const s = sections[ id ];
		if ( s && typeof s === 'object' ) out[ id ] = { version: Number( s.version ) || 1, data: s.data };
	}
	return JSON.stringify( {
		format: SETTINGS_FORMAT,
		formatVersion: SETTINGS_FORMAT_VERSION,
		created: new Date().toISOString(),
		source: source || {},
		sections: out,
	}, null, '\t' );
}


/**
 * Reads a backup file.
 *
 * @param {string} text
 * @return {{sections: object}}
 * @throws {Error} with the message 'format' when the file is not a backup of this kind, 'newer' when it was written
 *                 by a later format the dialog does not know
 */
export function parseBackup( text ) {
	let d;
	try { d = JSON.parse( String( text ) ); } catch ( e ) { throw new Error( 'format' ); }
	if ( ! d || d.format !== SETTINGS_FORMAT || typeof d.sections !== 'object' || ! d.sections ) throw new Error( 'format' );
	if ( Number( d.formatVersion ) > SETTINGS_FORMAT_VERSION ) throw new Error( 'newer' );
	const sections = {};
	for ( const id of Object.keys( d.sections ) ) {
		if ( ! /^[a-z0-9][a-z0-9-]{0,63}$/.test( id ) ) continue;
		const s = d.sections[ id ];
		if ( s && typeof s === 'object' ) sections[ id ] = { version: Number( s.version ) || 1, data: s.data };
	}
	return { sections };
}
